
function insta() {
    window.location = "https://www.instagram.com/kidkrishkode01/";
}
function login() {
    window.location = "https://vercel.com/login";
}
var countDownDate = new Date("Jan 26, 2027 00:00:00").getTime();
var x = setInterval(function () {
    var now = new Date().getTime();
    var distance = countDownDate - now;
    var days = Math.floor(distance / (1000 * 60 * 60 * 24));
    var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
    var seconds = Math.floor((distance % (1000 * 60)) / 1000);
    document.getElementById("countdown").innerHTML = (days < 10 ? '0' + days : days) + " Day " + (hours < 10 ? '0' + hours : hours) + " Hours "
        + (minutes < 10 ? '0' + minutes : minutes) + " Minutes " + (seconds < 10 ? '0' + seconds : seconds) + " Second ";
    if (distance < 0) {
        clearInterval(x);
        document.getElementById("countdown").innerHTML = "EXPIRED";
        window.location = "https://fundusguardai.vercel.app/";
    }
}, 1000);


for (let i = 0; i < 72; i++) {
    const cell = document.createElement('div');
    cell.className = 'grid-cell';
    document.body.appendChild(cell);
}
